window.QUESTIONS = [
  /* =================== VITESSE =================== */
  { id: "v1", t: "vitesse", g: true, r: ["W"], q: "En Wallonie, vous roulez hors agglomération sur une route ordinaire (une bande par sens), sans panneau de limitation. Vitesse maximale ?", o: ["70 km/h", "80 km/h", "90 km/h", "120 km/h"], a: 2, fix: true,
    e: "En Wallonie, la vitesse maximale hors agglomération est de 90 km/h, sauf panneau contraire.", p: "En Flandre, c'est 70 km/h par défaut hors agglomération depuis 2017. Ne confonds pas les deux Régions.", ref: "Code de la route, art. 11" },
  { id: "v2", t: "vitesse", g: true, r: ["F"], q: "En Flandre, hors agglomération, sur une route ordinaire sans panneau. Vitesse maximale ?", o: ["50 km/h", "70 km/h", "90 km/h"], a: 1, fix: true,
    e: "En Région flamande, la limite générale hors agglomération est de 70 km/h. 90 km/h n'est permis que là où c'est indiqué.", ref: "Code de la route, art. 11 (Région flamande)" },
  { id: "v3", t: "vitesse", g: true, r: ["B"], q: "À Bruxelles, dans une agglomération, sur une rue sans panneau de vitesse. Vitesse maximale ?", o: ["30 km/h", "50 km/h", "20 km/h"], a: 0, fix: true,
    e: "Depuis 2021 (« Ville 30 »), la vitesse par défaut en agglomération en Région de Bruxelles-Capitale est de 30 km/h. Les grands axes à 50 ou 70 km/h sont signalés.", ref: "Région de Bruxelles-Capitale, Ville 30" },
  { id: "v4", t: "vitesse", g: true, r: ["W", "F"], q: "Vous entrez dans une agglomération (panneau F1). Sans autre panneau, quelle est la vitesse maximale ?", s: "F1", o: ["30 km/h", "50 km/h", "70 km/h"], a: 1, fix: true,
    e: "En agglomération, la vitesse maximale est de 50 km/h, à partir du panneau F1 (nom de la localité sur fond blanc).", p: "La limite commence AU panneau, pas « un peu après ». Freine avant.", ref: "Art. 11.1" },
  { id: "v5", t: "vitesse", g: true, q: "Sur autoroute, sans indication contraire, la vitesse maximale pour une voiture est de :", o: ["100 km/h", "120 km/h", "130 km/h"], a: 1, fix: true,
    e: "120 km/h sur autoroute en Belgique. 130 km/h, c'est en France (par temps sec).", ref: "Art. 11.3" },
  { id: "v6", t: "vitesse", q: "Sur autoroute, existe-t-il une vitesse minimale (code actuel, jusqu'en mai 2027) ?", o: ["Oui, 70 km/h", "Oui, 50 km/h", "Non"], a: 0,
    e: "Le Code de la route actuel impose de pouvoir rouler et de rouler à au moins 70 km/h sur autoroute (sauf conditions de circulation). Le futur Code de la voie publique (1er juin 2027) supprime cette vitesse minimale.", p: "Question « piège 2027 » : ce qui compte à l'examen, c'est le code en vigueur le jour de l'examen.", ref: "Art. 21.4" },
  { id: "v7", t: "vitesse", g: true, q: "Dans une zone résidentielle ou zone de rencontre (F12a), la vitesse est limitée à :", s: "F12a", o: ["20 km/h", "30 km/h", "Au pas"], a: 0,
    e: "20 km/h maximum. Les piétons peuvent utiliser toute la largeur de la voie publique et les jeux y sont autorisés.", p: "« Au pas » (environ 6 km/h), c'est dans une zone piétonne ou une rue scolaire, pas en zone résidentielle.", ref: "Zone résidentielle / de rencontre (F12a)" },
  { id: "v8", t: "vitesse", g: true, q: "Ce panneau signifie :", s: "F4a", o: ["Vitesse limitée à 30 km/h jusqu'au prochain carrefour seulement", "Vitesse limitée à 30 km/h dans toute la zone, jusqu'au panneau de fin", "Vitesse conseillée de 30 km/h, sans obligation légale"], a: 1,
    e: "Le panneau F4a annonce une ZONE 30 : la limite vaut dans toutes les rues de la zone, même après les carrefours, jusqu'au panneau F4b.", p: "Le panneau rond C43 (30) seul, lui, vaut normalement jusqu'au prochain carrefour.", ref: "Zone 30 (F4a / F4b)" },
  { id: "v9", t: "vitesse", q: "Un panneau C43 « 70 » placé seul (sans répétition) est valable jusqu'à :", s: "C43_70", o: ["Le prochain carrefour", "La fin de la commune", "Un panneau de fin de limitation obligatoirement"], a: 0,
    e: "Une limitation par C43 cesse au prochain carrefour, sauf si elle est répétée après celui-ci ou si un panneau de fin (C45/C46) est placé plus loin.", ref: "Art. 68" },
  { id: "v10", t: "vitesse", q: "À quoi correspond ce panneau ?", s: "C45_70", o: ["Vitesse minimale 70 km/h", "Fin de la limitation à 70 km/h", "Vitesse de 70 km/h interdite aux camions"], a: 1,
    e: "Panneau blanc barré : fin de la limitation à 70 km/h. On revient à la vitesse générale de l'endroit (90 km/h en Wallonie hors agglo, par exemple).", ref: "C45" },
  { id: "v11", t: "vitesse", g: true, r: ["W"], q: "En Wallonie, hors agglomération, sur une route à 2 × 2 bandes séparées par une berme centrale (pas une autoroute), vitesse maximale sans panneau ?", o: ["90 km/h", "100 km/h", "120 km/h"], a: 2, fix: true,
    e: "Sur les routes à au moins 2 × 2 bandes séparées par une berme centrale, la limite générale est de 120 km/h en Wallonie, sauf panneau (souvent 90 km/h).", ref: "Art. 11.2" },
  { id: "v12", t: "vitesse", q: "La vitesse maximale autorisée signifie que :", o: ["Qu'on peut toujours rouler à cette vitesse, quelles que soient les conditions", "Qu'on ne peut pas la dépasser, et qu'on doit rouler moins vite si les conditions l'exigent", "Qu'on peut la dépasser de 10 % sans être verbalisé"], a: 1,
    e: "Règle de base (art. 10) : votre vitesse doit toujours être adaptée (météo, visibilité, densité du trafic, état de la route, chargement…) pour pouvoir vous arrêter devant un obstacle prévisible.", p: "Rouler à 90 dans le brouillard sur une route à 90 peut être une infraction (vitesse inadaptée).", ref: "Art. 10.1" },
  { id: "v13", t: "vitesse", q: "Dans une rue cyclable (F111), la vitesse maximale est de :", s: "F111", o: ["20 km/h", "30 km/h", "50 km/h"], a: 1,
    e: "30 km/h maximum dans une rue cyclable. Et surtout : les véhicules à moteur ne peuvent pas dépasser les cyclistes.", ref: "Rue cyclable (F111)" },
  { id: "v14", t: "vitesse", g: true, q: "Aux abords d'une école, signalés par une zone 30 « abords d'école » avec signaux lumineux ou panneau à message variable, vous devez :", s: "A23", o: ["Respecter 30 km/h aux heures indiquées ou quand le signal clignote", "Rouler au pas en permanence, même pendant les vacances scolaires", "Être prudent, mais la vitesse générale de 50 km/h reste permise"], a: 0,
    e: "Les zones 30 aux abords d'écoles peuvent être permanentes ou variables (horaires, signal clignotant). La limite de 30 km/h s'applique quand elle est d'application.", ref: "Zone 30 abords d'école" },
  { id: "v15", t: "vitesse", q: "Quelle est la vitesse maximale dans une zone piétonne, pour un véhicule autorisé à y circuler ?", s: "F103", o: ["Au pas", "10 km/h", "20 km/h"], a: 0,
    e: "Dans une zone piétonne, seuls certains véhicules autorisés (livraisons, riverains, secours…) peuvent circuler, et seulement au pas. Les piétons ont toujours la priorité.", ref: "Zone piétonne (F103)" },
  { id: "v16", t: "vitesse", q: "Quand vous doublez votre vitesse (par exemple de 50 à 100 km/h), votre distance de freinage est multipliée par environ :", o: ["2", "3", "4"], a: 2, fix: true,
    e: "La distance de freinage augmente avec le CARRÉ de la vitesse : ×2 de vitesse = ×4 de distance de freinage. C'est pour ça que quelques km/h de trop changent tout.", ref: "Physique / conduite défensive" },
  { id: "v17", t: "vitesse", q: "Le temps de réaction moyen d'un conducteur attentif est d'environ 1 seconde. À 90 km/h, combien de mètres parcourez-vous pendant ce temps ?", o: ["Environ 9 m", "Environ 25 m", "Environ 50 m"], a: 1, fix: true,
    e: "90 km/h = 25 m par seconde (90 ÷ 3,6). Avant même de toucher la pédale de frein, vous avez déjà parcouru 25 m. Avec la fatigue, l'alcool ou le GSM, ce temps double ou triple.", p: "Astuce : km/h ÷ 3,6 = m/s. Ou plus simplement : (dizaine de km/h) × 3 ≈ m/s.", ref: "Conduite défensive" },

  /* =================== PRIORITÉS =================== */
  { id: "p1", t: "priorite", g: true, q: "Carrefour sans panneau ni feu. Qui passe en premier ?", sc: { cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "B", from: "E", go: "straight", color: "#3c8dde" }] }, o: ["A", "B"], a: 1, fix: true,
    e: "Sans signalisation, c'est la priorité de droite. Pour A (qui monte vers le nord), B arrive de sa droite : A doit céder le passage à B.", ref: "Art. 12.3.1" },
  { id: "p2", t: "priorite", g: true, q: "Carrefour sans panneau ni feu. Qui passe en premier ?", sc: { cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "B", from: "W", go: "straight", color: "#3c8dde" }] }, o: ["A", "B"], a: 0, fix: true,
    e: "B vient de la GAUCHE de A. A a donc la priorité de droite sur B… et B doit céder le passage à A (A est à sa droite).", ref: "Art. 12.3.1" },
  { id: "p3", t: "priorite", g: true, q: "A voit un panneau « cédez le passage » à son entrée. Qui passe en premier ?", sc: { cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "B", from: "W", go: "straight", color: "#3c8dde" }], signs: { S: "B1" } }, o: ["A", "B"], a: 1, fix: true,
    e: "Le B1 oblige A à céder le passage aux usagers des DEUX côtés, même à ceux qui viennent de la gauche. La signalisation l'emporte sur la priorité de droite.", ref: "Art. 12.3.2 / B1" },
  { id: "p4", t: "priorite", g: true, q: "Carrefour sans signalisation. A veut tourner à gauche, B arrive en face et va tout droit. Qui passe en premier ?", sc: { cars: [{ id: "A", from: "S", go: "left", color: "#e8553f" }, { id: "B", from: "N", go: "straight", color: "#3c8dde" }] }, o: ["A", "B"], a: 1, fix: true,
    e: "Le conducteur qui tourne à gauche doit céder le passage aux conducteurs qui viennent en sens inverse sur la chaussée qu'il quitte.", ref: "Art. 19.5" },
  { id: "p5", t: "priorite", g: true, q: "Carrefour sans signalisation, trois véhicules arrivent en même temps. Dans quel ordre passent-ils ?", sc: { cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "B", from: "W", go: "straight", color: "#3c8dde" }, { id: "C", from: "E", go: "straight", color: "#26a269" }] }, o: ["C, puis A, puis B", "A, puis B, puis C", "B, puis A, puis C", "C, puis B, puis A"], a: 0,
    e: "Raisonne véhicule par véhicule. A a C à sa droite → A attend C. B a A à sa droite → B attend A. C n'a personne à sa droite → C passe en premier. Donc : C, A, puis B.", p: "Méthode : cherche celui qui n'a PERSONNE à sa droite. Il passe le premier.", ref: "Art. 12.3.1" },
  { id: "p6", t: "priorite", g: true, q: "Carrefour sans signalisation. Le tram arrive de la gauche de A. Qui passe en premier ?", sc: { tram: true, cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "T", from: "W", go: "straight", color: "#f2c037", tram: true }] }, o: ["A, car le tram vient de sa gauche", "Le tram"], a: 1, fix: true,
    e: "La priorité de droite ne joue pas contre le tram : sauf signalisation contraire (feux, agent, panneau pour le tram), le tram a la priorité, d'où qu'il vienne.", p: "Un tram ne peut ni dévier ni freiner court. Dans le doute, il passe.", ref: "Art. 12.3.1" },
  { id: "p7", t: "priorite", g: true, q: "A circule sur une route prioritaire. B arrive de la droite. Qui passe en premier ?", sc: { cars: [{ id: "A", from: "S", go: "straight", color: "#e8553f" }, { id: "B", from: "E", go: "straight", color: "#3c8dde" }], signs: { S: "B9", E: "B1" } }, o: ["A", "B"], a: 0, fix: true,
    e: "A est sur une route prioritaire (B9) et B a un « cédez le passage » (B1) : A passe, même si B vient de sa droite.", ref: "B9 / B1" },
  { id: "p8", t: "priorite", g: true, q: "Que signifie ce panneau ?", s: "B15", o: ["Carrefour avec priorité de droite", "Priorité au prochain carrefour seulement", "Croisement avec une voie ferrée"], a: 1,
    e: "B15 : au PROCHAIN carrefour, vous avez la priorité sur ceux qui viennent des routes latérales. Après ce carrefour, la priorité de droite revient (sauf autre panneau).", p: "Ne confonds pas avec le B17 (croix en X) qui annonce au contraire la priorité de droite.", ref: "B15" },
  { id: "p9", t: "priorite", g: true, q: "Que signifie ce panneau ?", s: "B17", o: ["Carrefour où la priorité de droite s'applique", "Passage à niveau sans barrières à l'approche", "Croisement avec une route prioritaire pour vous"], a: 0,
    e: "B17 : carrefour à priorité de droite. Soyez prêt à céder le passage à ceux qui viennent de droite.", ref: "B17" },
  { id: "p10", t: "priorite", g: true, q: "Vous êtes face à ce panneau, aucun véhicule n'arrive, la visibilité est parfaite. Que faites-vous ?", s: "B5", o: ["Je ralentis fortement et je passe sans m'arrêter si c'est libre", "Je m'arrête complètement à la ligne, puis je repars si c'est libre", "Je m'arrête seulement si un véhicule arrive de ma droite"], a: 1,
    e: "STOP = arrêt complet obligatoire, toujours, à la ligne d'arrêt (ou à défaut au bord de la chaussée abordée). Ensuite seulement, on cède le passage dans les deux sens.", p: "Le « stop glissé » est une faute grave à l'examen pratique… et une infraction.", ref: "B5" },
  { id: "p11", t: "priorite", g: true, q: "Vous entrez dans un rond-point signalé par les panneaux D5 et B1. Qui a la priorité ?", s: "D5", o: ["Moi, car je viens de la droite", "Les usagers déjà engagés sur le rond-point", "Le plus gros véhicule"], a: 1,
    e: "Un carrefour giratoire signalé (D5 + B1) : vous cédez le passage à ceux qui circulent déjà sur l'anneau.", ref: "Art. 12.3.2 / D5" },
  { id: "p12", t: "priorite", g: true, q: "Vous sortez d'un parking de supermarché pour vous engager sur la voie publique. Un cycliste arrive de votre gauche. Que faites-vous ?", o: ["Je passe : il vient de ma gauche, donc il doit me céder", "Je lui cède le passage : en sortant d'un parking, je cède à tous", "Je m'engage : un cycliste doit céder aux voitures"], a: 1,
    e: "Celui qui sort d'un parking, d'une propriété, d'un chemin de terre, d'une station-service ou d'une zone résidentielle cède le passage à TOUS les usagers, de gauche comme de droite (cyclistes et piétons compris).", ref: "Art. 12.4" },
  { id: "p13", t: "priorite", g: true, q: "Vous démarrez après avoir été garé le long du trottoir. Qui doit céder le passage ?", o: ["Moi, à tous les autres usagers", "Les véhicules qui arrivent derrière moi, si j'ai mis mon clignotant", "Personne, c'est au premier qui passe"], a: 0,
    e: "Toute manœuvre (démarrer, changer de bande, faire demi-tour, marche arrière…) oblige à céder le passage aux autres usagers. Le clignotant annonce la manœuvre, il ne donne aucune priorité.", ref: "Art. 12.4" },
  { id: "p14", t: "priorite", g: true, q: "Un véhicule de police arrive derrière vous avec feux bleus clignotants ET sirène. Vous devez :", o: ["Continuer normalement, il me dépassera", "Lui libérer le passage, et si nécessaire m'arrêter", "Accélérer pour ne pas le gêner"], a: 1,
    e: "Les véhicules prioritaires utilisant feu bleu ET avertisseur sonore spécial : chacun doit leur céder le passage et, si nécessaire, s'arrêter. Ils peuvent même passer au rouge… mais pas vous pour les suivre.", ref: "Art. 37 / 38" },
  { id: "p15", t: "priorite", q: "Un véhicule avec un gyrophare ORANGE clignotant (dépanneuse, véhicule lent, voirie). Est-il prioritaire ?", o: ["Oui, il a les mêmes droits qu'un véhicule avec feu bleu", "Non : le feu orange signale un danger, pas une priorité"], a: 1,
    e: "Le feu orange clignotant signale un danger (véhicule lent, exceptionnel, travaux, dépanneuse…). Il ne donne aucune priorité : soyez prudent et adaptez votre vitesse.", ref: "Art. 37" },
  { id: "p16", t: "priorite", g: true, q: "Ce panneau est placé avant un passage étroit. Que devez-vous faire ?", s: "B19", o: ["Je passe en premier, j'ai la priorité dans ce passage", "Je laisse passer ceux qui arrivent en sens inverse", "Le premier arrivé à l'entrée du passage passe"], a: 1,
    e: "B19 (flèche rouge = vous) : vous devez céder le passage aux conducteurs venant en sens inverse dans ce passage étroit.", p: "B21 (carré bleu, flèche blanche = vous) : c'est l'inverse, vous êtes prioritaire.", ref: "B19" },
  { id: "p17", t: "priorite", q: "Ce panneau vous concerne. Que signifie-t-il ?", s: "B21", o: ["Vous avez la priorité sur les conducteurs venant en sens inverse", "Vous devez céder le passage aux conducteurs d'en face", "Voie à sens unique"], a: 0,
    e: "B21 : priorité par rapport aux conducteurs venant en sens inverse dans le passage étroit (flèche blanche = vous).", ref: "B21" },
  { id: "p18", t: "priorite", g: true, q: "Vous sortez d'une zone résidentielle (F12b) pour rejoindre une rue ordinaire. Une voiture arrive de votre gauche.", o: ["J'ai la priorité, elle vient de ma gauche", "Je lui cède le passage", "Elle doit s'arrêter car je sors d'une zone protégée"], a: 1,
    e: "En sortant d'une zone résidentielle ou de rencontre, vous cédez le passage à tous les autres usagers, comme si vous sortiez d'une propriété.", ref: "Art. 12.4" },
  { id: "p19", t: "priorite", g: true, q: "Panneau B9 « route prioritaire » sur votre route, et un agent qualifié vous fait signe de vous arrêter. Qui l'emporte ?", s: "B9", o: ["Le panneau", "L'agent", "La priorité de droite"], a: 1,
    e: "Hiérarchie : 1) injonctions des agents qualifiés, 2) signaux lumineux, 3) panneaux et marquages, 4) règles générales (priorité de droite).", p: "Retiens : Agent > Feux > Panneaux > Règles.", ref: "Art. 6 & 7" },
  { id: "p20", t: "priorite", g: true, q: "Ce panneau marque la fin de la route prioritaire. Au prochain carrefour, sans autre signal :", s: "B11", o: ["Vous gardez la priorité", "La priorité de droite s'applique", "Vous devez vous arrêter"], a: 1,
    e: "B11 = fin de route prioritaire. Sans autre signalisation, c'est la règle générale : priorité de droite.", ref: "B11" },
  { id: "p21", t: "priorite", g: true, q: "Vous tournez à droite à un carrefour. Un piéton traverse la rue dans laquelle vous vous engagez. Que faites-vous ?", sc: { cars: [{ id: "A", from: "S", go: "right", color: "#e8553f" }], zebra: "E", ped: [212, 205] }, o: ["Je passe, j'ai le feu vert", "Je laisse traverser le piéton", "Je klaxonne"], a: 1,
    e: "En changeant de direction, vous devez céder le passage aux piétons et cyclistes qui traversent la chaussée dans laquelle vous vous engagez, même si votre feu est vert.", ref: "Art. 19.6 / 40" },

  /* =================== PANNEAUX =================== */
  { id: "s1", t: "panneaux", q: "Que signifie ce panneau ?", s: "C1", o: ["Sens interdit pour tous les conducteurs", "Arrêt et stationnement interdits de ce côté", "Fin de la route prioritaire au prochain carrefour"], a: 0,
    e: "C1 : accès interdit dans ce sens à tout conducteur. Un panneau additionnel M peut autoriser les cyclistes (sens unique limité).", ref: "C1" },
  { id: "s2", t: "panneaux", q: "Que signifie ce panneau ?", s: "C3", o: ["Accès interdit à tout conducteur, dans les deux sens", "Stationnement interdit sur toute la longueur de la rue", "Route fermée aux piétons, ouverte aux véhicules"], a: 0,
    e: "C3 : interdiction d'accès à tout conducteur, dans les deux sens. Les piétons peuvent passer. Utilisé aussi pour les rues scolaires, avec panneau additionnel.", p: "Cercle blanc bordé de rouge VIDE = C3. Rond rouge avec barre blanche = C1 (sens interdit).", ref: "C3" },
  { id: "s3", t: "panneaux", q: "Ce panneau vous interdit de :", s: "C35", o: ["Dépasser une moto ou un cyclomoteur par la gauche", "Dépasser un véhicule à plus de deux roues par la gauche", "Changer de bande, même pour tourner"], a: 1,
    e: "C35 : interdit de dépasser par la gauche un véhicule à plus de deux roues. Vous pouvez toujours dépasser un vélo, un cyclomoteur ou une moto (deux roues).", ref: "C35" },
  { id: "s4", t: "panneaux", q: "Que signifie ce panneau ?", s: "E1", o: ["Arrêt et stationnement interdits", "Stationnement interdit (l'arrêt est permis)", "Sens interdit"], a: 1,
    e: "E1 (une barre) : stationnement interdit, mais vous pouvez vous arrêter le temps de faire monter/descendre quelqu'un ou de charger/décharger.", p: "Une barre = pas de stationnement. Deux barres (croix) = pas d'arrêt NI de stationnement.", ref: "E1" },
  { id: "s5", t: "panneaux", q: "Que signifie ce panneau ?", s: "E3", o: ["Arrêt et stationnement interdits", "Stationnement alterné", "Fin d'interdiction de stationner"], a: 0,
    e: "E3 (croix) : interdiction de s'arrêter et de stationner du côté où se trouve le panneau.", ref: "E3" },
  { id: "s6", t: "panneaux", q: "Ce panneau signale :", s: "A43", o: ["Un passage à niveau avec barrières", "Un passage à niveau sans barrières", "Une gare"], a: 1,
    e: "A43 (locomotive) : passage à niveau SANS barrières. A41 (barrière) : avec barrières ou demi-barrières.", p: "Dessin de barrière = barrières. Dessin de train = PAS de barrières… donc encore plus de vigilance.", ref: "A41 / A43" },
  { id: "s7", t: "panneaux", q: "Que signifie ce panneau ?", s: "A51", o: ["Danger non précisé (autre danger)", "Information touristique", "Fin de tous les dangers"], a: 0,
    e: "A51 : danger qui n'est pas représenté par un autre panneau. Souvent complété par un panneau additionnel qui en précise la nature.", ref: "A51" },
  { id: "s8", t: "panneaux", q: "Ce panneau signale :", s: "A23", o: ["Un passage pour piétons à environ 150 m", "Un endroit fréquenté par des enfants", "Une zone piétonne interdite aux voitures"], a: 1,
    e: "A23 : endroit particulièrement fréquenté par des enfants (école, plaine de jeux). A21, lui, annonce un passage pour piétons.", ref: "A23" },
  { id: "s9", t: "panneaux", q: "Hors agglomération, à quelle distance environ les panneaux de danger sont-ils généralement placés avant le danger ?", o: ["50 m", "150 m", "500 m"], a: 1, fix: true,
    e: "Hors agglomération, les panneaux de danger sont en principe placés à environ 150 m du danger. En agglomération, ils peuvent être placés plus près. Un panneau additionnel peut indiquer une autre distance.", ref: "Art. 66" },
  { id: "s10", t: "panneaux", q: "Que signifie ce panneau bleu rond ?", s: "D1", o: ["Une voie publique à sens unique", "L'obligation de suivre la direction indiquée", "Le début d'une route pour automobiles"], a: 1,
    e: "Rond bleu = obligation. D1 : direction obligatoire. Rectangle bleu avec flèche (F19) = simple indication de sens unique.", ref: "D1" },
  { id: "s11", t: "panneaux", q: "Que signifie ce panneau ?", s: "F19", o: ["Direction obligatoire", "Voie publique à sens unique", "Priorité"], a: 1,
    e: "F19 : vous êtes dans une rue à sens unique. C'est une indication (carré bleu), pas une obligation comme le D1 (rond bleu).", ref: "F19" },
  { id: "s12", t: "panneaux", q: "Que signifie ce panneau ?", s: "C46", o: ["Fin de toutes les interdictions locales (véhicules en mouvement)", "Fin de l'agglomération : on reprend la vitesse hors agglomération", "Interdiction de circuler pour tous les véhicules, dans les deux sens"], a: 0,
    e: "C46 : fin de toutes les interdictions locales (vitesse, dépassement…) signalées pour les véhicules en mouvement.", ref: "C46" },
  { id: "s13", t: "panneaux", q: "Ce panneau signale :", s: "F45", o: ["Une voie sans issue", "Un hôpital", "Un parking"], a: 0, e: "F45 : voie sans issue (impasse).", ref: "F45" },
  { id: "s14", t: "panneaux", q: "Quel panneau oblige les cyclistes à emprunter la piste qui leur est réservée ?", s: "D7", o: ["Celui-ci (D7)", "Le A25", "Le C11"], a: 0,
    e: "D7 : piste cyclable obligatoire. A25 = danger (passage de cyclistes). C11 = accès interdit aux cyclistes.", ref: "D7" },
  { id: "s15", t: "panneaux", q: "Que signifie ce panneau ?", s: "C33", o: ["Demi-tour interdit", "Virage dangereux", "Tourner à gauche interdit"], a: 0,
    e: "C33 : interdiction de faire demi-tour jusqu'au prochain carrefour inclus.", ref: "C33" },
  { id: "s16", t: "panneaux", q: "Ce panneau annonce :", s: "A39", o: ["Une circulation dans les deux sens", "Une route à sens unique", "Un rétrécissement de chaussée"], a: 0,
    e: "A39 : la circulation redevient à double sens (par exemple après une portion à sens unique ou une chaussée séparée).", ref: "A39" },
  { id: "s17", t: "panneaux", q: "Ce panneau signifie :", s: "F99a", o: ["Chemin réservé aux usagers représentés (piétons, cyclistes)", "Zone 30 partagée entre voitures et cyclistes", "Piste cyclable conseillée, les voitures y sont admises"], a: 0,
    e: "F99a : chemin réservé aux catégories d'usagers représentées. Les autres véhicules sont interdits (sauf exceptions indiquées, ex. riverains, agriculture).", ref: "F99a" },
  { id: "s18", t: "panneaux", q: "Ce panneau vous interdit :", s: "C31a", o: ["De tourner à gauche", "De faire demi-tour", "De dépasser à gauche"], a: 0, e: "C31a : interdiction de tourner à gauche au prochain carrefour.", ref: "C31" },
  { id: "s19", t: "panneaux", q: "Ce panneau signale :", s: "A15", o: ["Une chaussée glissante", "Une route sinueuse", "Une sortie de garage"], a: 0, e: "A15 : chaussée glissante. On ralentit, on augmente les distances, on évite les gestes brusques.", ref: "A15" },
  { id: "s20", t: "panneaux", q: "Ce panneau signifie :", s: "F9", o: ["Route pour automobiles", "Parking pour voitures", "Garage"], a: 0,
    e: "F9 : route pour automobiles. Réservée aux véhicules automobiles ; il y est interdit de faire demi-tour, de faire marche arrière, de s'arrêter hors des endroits prévus… comme sur autoroute (la vitesse dépend de l'endroit).", ref: "F9 / art. 22" },
  { id: "s21", t: "panneaux", q: "Les panneaux de forme triangulaire, pointe vers le haut, bordés de rouge, sont des panneaux de :", s: "A1a", o: ["Danger", "Interdiction", "Obligation"], a: 0,
    e: "Triangle pointe en haut = danger (A). Rond bordé de rouge = interdiction (C). Rond bleu = obligation (D). Carré/rectangle = indication (F) ou stationnement (E).", ref: "Catégories de signaux" },
  { id: "s22", t: "panneaux", q: "Un panneau additionnel (sous un panneau principal) :", o: ["Précise ou limite la portée du panneau principal", "Annule le panneau principal en dehors des heures de pointe", "N'a qu'une valeur de conseil, sans obligation"], a: 0,
    e: "Les panneaux additionnels précisent la portée : distance, longueur, catégories de véhicules concernées, heures, exceptions…", ref: "Art. 65" },

  /* =================== FEUX, AGENTS, MARQUAGES =================== */
  { id: "f1", t: "feux", g: true, q: "Le feu passe à l'orange fixe alors que vous êtes encore assez loin pour vous arrêter en sécurité. Vous :", o: ["Accélérez pour passer", "Vous arrêtez", "Passez si personne ne traverse"], a: 1,
    e: "Feu orange fixe = interdiction de franchir la ligne d'arrêt, sauf si vous en êtes si près que vous ne pouvez plus vous arrêter en sécurité.", p: "L'orange n'est pas un « vert prolongé » : c'est un ordre de s'arrêter.", ref: "Art. 61.1" },
  { id: "f2", t: "feux", q: "Un feu orange clignotant signifie :", o: ["Arrêt obligatoire, exactement comme un feu rouge fixe", "Passage permis avec prudence, en appliquant les priorités", "Le feu va passer au vert : on peut déjà s'avancer"], a: 1,
    e: "Orange clignotant : feux hors service ou en mode nuit. Vous passez avec prudence en appliquant les panneaux… ou à défaut la priorité de droite.", ref: "Art. 61.1" },
  { id: "f3", t: "feux", g: true, q: "Feu vert, mais le carrefour est encombré : si vous vous engagez, vous allez rester bloqué au milieu. Vous :", o: ["M'engage quand même, j'ai le vert", "Attends avant la ligne d'arrêt", "Klaxonne"], a: 1,
    e: "Il est interdit de s'engager dans un carrefour si l'encombrement risque de vous y immobiliser et de gêner la circulation transversale, même au vert.", ref: "Art. 12.5" },
  { id: "f4", t: "feux", q: "Une flèche orange clignotante est allumée à côté d'un feu rouge, dans votre direction. Vous pouvez :", o: ["Passer dans la direction de la flèche en cédant aux piétons et cyclistes", "Passer dans la direction de la flèche sans devoir céder le passage", "Rien : le feu rouge l'emporte sur la flèche"], a: 0,
    e: "La flèche orange clignotante autorise à continuer dans la direction indiquée, à condition de céder le passage aux usagers qui circulent normalement (souvent piétons et cyclistes).", ref: "Art. 61.4" },
  { id: "f5", t: "feux", g: true, q: "Un agent qualifié se tient face à vous, bras tendu à l'horizontale. Cela signifie :", o: ["Arrêt pour ceux qui arrivent face à lui ou dans son dos", "Passage libre pour ceux qui arrivent face à lui", "Ralentir, sans obligation de s'arrêter"], a: 0,
    e: "Bras tendu horizontalement : arrêt pour les usagers venant de directions qui coupent celle indiquée par le(s) bras (de face et de dos). Bras levé verticalement : arrêt pour tous (sauf ceux déjà engagés dans le carrefour).", ref: "Art. 4" },
  { id: "f6", t: "feux", g: true, q: "Le feu est vert mais un agent vous fait signe de vous arrêter. Vous :", o: ["Passez : le feu est vert", "Vous arrêtez", "Klaxonnez pour qu'il bouge"], a: 1, e: "Les injonctions d'un agent qualifié priment sur les feux, panneaux et règles.", ref: "Art. 6" },
  { id: "f7", t: "feux", g: true, q: "Une ligne blanche continue au milieu de la chaussée signifie :", o: ["Interdiction de la franchir ou de la chevaucher", "On peut la franchir pour dépasser", "On peut la chevaucher pour éviter un trou"], a: 0,
    e: "Ligne blanche continue : interdit de la franchir et de la chevaucher. Ligne discontinue : franchissable pour dépasser ou tourner si c'est sûr.", ref: "Art. 72" },
  { id: "f8", t: "feux", q: "Une ligne jaune discontinue le long du bord de la chaussée signifie :", o: ["Stationnement interdit", "Arrêt et stationnement interdits", "Piste cyclable"], a: 0,
    e: "Ligne jaune discontinue au bord : stationnement interdit. Ligne jaune continue : arrêt et stationnement interdits.", p: "Même logique que les panneaux : discontinue = E1 ; continue = E3.", ref: "Art. 75" },
  { id: "f9", t: "feux", q: "Des triangles blancs (« dents de requin ») sont peints en travers de votre bande. Ils signifient :", o: ["Ralentisseur", "Cédez le passage", "Passage pour piétons"], a: 1,
    e: "La ligne de triangles blancs indique l'endroit où vous devez céder le passage (équivalent au panneau B1).", ref: "Art. 76.3" },
  { id: "f10", t: "feux", q: "Un feu pour cyclistes affiche un vélo et vous êtes en voiture. Vous en tenez compte ?", o: ["Oui, tous les feux s'adressent à tous les conducteurs", "Non, il ne concerne que les cyclistes (et usagers de la piste)"], a: 1,
    e: "Les feux avec silhouette de vélo ne s'adressent qu'aux cyclistes (et autres usagers de la piste). Vous suivez le feu destiné aux véhicules.", ref: "Art. 62" },
  { id: "f11", t: "feux", g: true, q: "Au passage à niveau, les feux rouges clignotent alternativement mais aucune barrière n'est encore baissée. Vous :", o: ["Passez vite avant les barrières", "Vous arrêtez", "Passez si aucun train n'est visible"], a: 1,
    e: "Les feux rouges clignotants alternatifs d'un passage à niveau interdisent de s'y engager. Un train peut arriver très vite (et un second train peut suivre).", ref: "Art. 61.2 / 34" },
  { id: "f12", t: "feux", g: true, q: "Vous êtes à l'arrêt au feu rouge. Un panneau B22 (vélo + flèche orange) est placé sous le feu. À qui s'adresse-t-il ?", o: ["Aux cyclistes : tourner à droite au rouge en cédant le passage", "À tous : on peut tourner à droite au rouge en cédant le passage", "Aux bus et taxis qui tournent à droite"], a: 0,
    e: "Les panneaux B22/B23 permettent uniquement aux cyclistes (et cyclomotoristes A, speed pedelecs selon le cas) de franchir le feu rouge pour tourner à droite ou aller tout droit, en cédant le passage. Pour une voiture, le rouge reste rouge.", ref: "B22 / B23" },
  { id: "f13", t: "feux", q: "Un marquage en damier (blocs blancs) au sol à travers la chaussée indique :", o: ["Un passage pour cyclistes et cyclomotoristes", "Un passage pour piétons en zone scolaire", "Une ligne d'arrêt pour les véhicules"], a: 0,
    e: "Deux lignes discontinues de carrés blancs = passage pour cyclistes et cyclomotoristes à deux roues. Les bandes blanches parallèles à l'axe de la route (« zébra ») = passage pour piétons.", ref: "Marquages : passages" },
  { id: "f14", t: "feux", q: "Une bande délimitée par une ligne blanche et marquée « BUS » est :", o: ["Réservée aux bus (et aux usagers autorisés par panneau)", "Accessible à tous en dehors des heures de pointe", "Réservée aux taxis et aux véhicules électriques"], a: 0,
    e: "La bande bus est réservée aux bus et, selon la signalisation, à certains autres (taxis, cyclistes…). Les autres véhicules peuvent seulement la franchir pour tourner ou accéder à une propriété, sans y circuler.", ref: "Marquages : bande bus" },

  /* =================== CROISEMENT & DÉPASSEMENT =================== */
  { id: "d1", t: "depassement", g: true, q: "En règle générale, on dépasse :", o: ["Par la gauche", "Par la droite", "Du côté le plus libre"], a: 0, e: "On dépasse par la gauche. Exceptions : par la droite un véhicule qui s'est mis à gauche pour tourner à gauche, et le tram s'il circule au milieu.", ref: "Art. 16.2" },
  { id: "d2", t: "depassement", q: "Un véhicule devant vous s'est déporté vers le milieu et met son clignotant à gauche pour tourner. Vous pouvez :", o: ["Le dépasser par la droite s'il reste assez de place", "Attendre derrière lui, le dépassement par la droite étant interdit", "Le dépasser par la gauche en franchissant l'axe"], a: 0, e: "Exception à la règle : un véhicule qui tourne à gauche et s'est porté vers la gauche se dépasse par la DROITE.", ref: "Art. 16.3" },
  { id: "d3", t: "depassement", g: true, q: "En agglomération, vous dépassez un cycliste. Distance latérale minimale ?", o: ["0,5 m", "1 m", "1,5 m"], a: 1, fix: true,
    e: "Distance latérale d'au moins 1 m en agglomération et 1,5 m hors agglomération pour dépasser un cycliste ou un cyclomotoriste à deux roues. Si ce n'est pas possible : vous attendez.", p: "Retiens « 1 – 1,5 » : 1 m en ville, 1,5 m hors agglomération.", ref: "Art. 40ter" },
  { id: "d4", t: "depassement", g: true, q: "Hors agglomération, vous dépassez un cycliste. Distance latérale minimale ?", o: ["1 m", "1,5 m", "2 m"], a: 1, fix: true, e: "1,5 m hors agglomération (1 m en agglomération).", ref: "Art. 40ter" },
  { id: "d5", t: "depassement", g: true, q: "Dans quelle situation le dépassement est-il interdit ?", o: ["Au sommet d'une côte ou dans un virage sans visibilité", "Sur une route droite, si la ligne médiane est discontinue", "Quand le véhicule devant roule sous la limite de vitesse"], a: 0,
    e: "Il est interdit de dépasser quand la visibilité est insuffisante (sommet de côte, virage), sauf s'il y a au moins deux bandes dans votre sens ou s'il s'agit d'un deux-roues et que la visibilité reste suffisante.", ref: "Art. 17.2" },
  { id: "d6", t: "depassement", g: true, q: "Une voiture s'est arrêtée devant un passage pour piétons pour laisser traverser. Vous :", o: ["La dépassez prudemment", "Vous arrêtez aussi derrière elle", "Klaxonnez"], a: 1,
    e: "Il est interdit de dépasser un véhicule qui s'arrête ou est arrêté devant un passage pour piétons : il cache peut-être un piéton en train de traverser.", ref: "Art. 40.4" },
  { id: "d7", t: "depassement", g: true, q: "Vous êtes en train d'être dépassé. Vous devez :", o: ["Garder votre droite et ne pas accélérer", "Accélérer légèrement pour raccourcir son dépassement", "Vous déporter vers le milieu pour mieux le voir"], a: 0, e: "Celui qui est dépassé doit serrer à droite autant que possible et ne pas augmenter sa vitesse.", ref: "Art. 16.5" },
  { id: "d8", t: "depassement", g: true, q: "Avant de dépasser, vous devez notamment vérifier que :", o: ["Que personne n'a commencé à vous dépasser et que la voie est libre assez loin", "Que le véhicule devant roule au moins 20 km/h sous la limite", "Que vous avez actionné l'avertisseur sonore, même en agglomération"], a: 0,
    e: "Avant de dépasser : rétroviseurs + angle mort, personne n'a commencé à vous dépasser, le conducteur devant n'a pas signalé qu'il allait dépasser ou tourner à gauche, la voie est libre assez loin, et vous pourrez vous rabattre sans gêner.", ref: "Art. 16.4" },
  { id: "d9", t: "depassement", q: "Peut-on dépasser un tram par la droite ?", o: ["Oui, s'il roule au milieu et qu'il reste assez de place", "Non, jamais : un tram se dépasse toujours par la gauche", "Seulement quand il est arrêté à un quai, à vitesse réduite"], a: 0,
    e: "Un tram se dépasse par la droite lorsque l'espace entre lui et le bord droit est suffisant. On peut le dépasser par la gauche sur une voie à sens unique, ou s'il n'y a pas assez de place à droite et que la voie est libre.", ref: "Art. 16.3" },
  { id: "d10", t: "depassement", q: "Sur une chaussée étroite, un autre véhicule arrive en face. Que dit la règle ?", o: ["Chacun serre à droite ; celui qui a l'obstacle cède", "Le véhicule le plus rapide passe, l'autre se range sur le côté", "Le véhicule le plus lourd passe, l'autre doit reculer"], a: 0, e: "Pour croiser, chacun serre à droite. Celui dont la partie de chaussée est obstruée par un obstacle laisse passer celui d'en face.", ref: "Art. 15" },
  { id: "d11", t: "depassement", g: true, q: "Une bande de circulation disparaît (travaux, rétrécissement). Comment vous insérez-vous ?", o: ["Le plus tôt possible", "En tirette : on roule jusqu'au rétrécissement puis on s'insère alternativement, un véhicule de chaque bande", "Celui de la bande qui continue a toujours la priorité absolue et ne laisse passer personne"], a: 1,
    e: "La tirette (fermeture éclair) est obligatoire en Belgique : en cas de réduction du nombre de bandes, les conducteurs s'insèrent alternativement, juste avant le rétrécissement.", p: "S'insérer trop tôt crée des bouchons. Laisser passer « son » véhicule est une obligation, pas une politesse.", ref: "Art. 12bis" },

  /* =================== ARRÊT & STATIONNEMENT =================== */
  { id: "st1", t: "stationnement", q: "Quelle est la différence entre « arrêt » et « stationnement » ?", o: ["Arrêt : le temps de faire monter/descendre ou de charger ; au-delà, stationnement", "Il n'y en a pas : les deux mots désignent la même chose dans le Code", "Arrêt : moteur allumé ; stationnement : moteur éteint, quelle que soit la durée"], a: 0,
    e: "Arrêt = immobilisation le temps nécessaire pour embarquer/débarquer des personnes ou des choses. Stationnement = toute autre immobilisation (au-delà de ce temps). Le moteur n'a rien à voir.", ref: "Art. 2.22-2.23" },
  { id: "st2", t: "stationnement", q: "En règle générale, vous devez vous arrêter ou stationner :", o: ["À droite par rapport à votre sens de marche", "Du côté où il reste de la place", "N'importe où sur le trottoir"], a: 0,
    e: "On s'arrête et on stationne à droite. Exception : dans une rue à sens unique, on peut aussi le faire à gauche.", ref: "Art. 23.1" },
  { id: "st3", t: "stationnement", g: true, q: "À quelle distance minimale d'un passage pour piétons est-il interdit de s'arrêter et de stationner (avant le passage) ?", o: ["2 m", "5 m", "10 m"], a: 1, fix: true,
    e: "Arrêt et stationnement interdits sur les passages pour piétons et cyclistes, et sur la chaussée à moins de 5 m avant ceux-ci. Un véhicule garé là cache les enfants qui traversent.", ref: "Art. 24" },
  { id: "st4", t: "stationnement", q: "Il est interdit de s'arrêter et de stationner à moins de ___ du prolongement du bord le plus rapproché de la chaussée transversale (carrefour), sauf aménagement :", o: ["3 m", "5 m", "15 m"], a: 1, fix: true, e: "5 m d'un carrefour : stationnement et arrêt interdits, sauf emplacements marqués.", ref: "Art. 24" },
  { id: "st5", t: "stationnement", q: "Le stationnement est interdit à moins de combien de mètres de part et d'autre d'un panneau d'arrêt de bus ou de tram ?", o: ["5 m", "15 m", "30 m"], a: 1, fix: true, e: "Stationnement interdit à moins de 15 m de part et d'autre d'un arrêt de bus, tram ou trolleybus.", ref: "Art. 25" },
  { id: "st6", t: "stationnement", q: "En zone bleue (disque), sauf indication contraire, la durée maximale de stationnement est de :", s: "E9a_disque", o: ["1 h", "2 h", "3 h"], a: 1, fix: true,
    e: "En zone bleue, le disque est obligatoire et la durée maximale est en principe de 2 h, les jours ouvrables de 9 h à 18 h (sauf indication contraire).", p: "Le disque se règle sur le trait qui suit l'heure d'arrivée (on arrondit vers la demi-heure suivante).", ref: "Art. 27.1" },
  { id: "st7", t: "stationnement", g: true, q: "Peut-on stationner sur un trottoir ?", o: ["Oui, si on laisse au moins 1 m de passage aux piétons", "Non, sauf si une signalisation le permet expressément", "Oui, en agglomération, pour moins de 2 heures"], a: 1,
    e: "Le stationnement (et l'arrêt) sur les trottoirs et les pistes cyclables est interdit, sauf réglementation locale/marquage qui l'autorise. Il faut laisser au moins 1,5 m aux piétons là où c'est autorisé.", ref: "Art. 24" },
  { id: "st8", t: "stationnement", q: "Dans une zone résidentielle ou de rencontre, où pouvez-vous stationner ?", s: "F12a", o: ["Partout sur la chaussée, tant qu'on ne gêne pas", "Uniquement aux emplacements délimités (marquage, revêtement, P)", "Sur les trottoirs, la chaussée étant réservée aux piétons"], a: 1, e: "Dans une zone résidentielle/de rencontre, le stationnement n'est autorisé qu'aux emplacements délimités par un marquage, un revêtement différent ou un signal P.", ref: "Zone résidentielle / de rencontre (F12a)" },
  { id: "st9", t: "stationnement", q: "Vous vous arrêtez quelques minutes pour déposer un passager sous ce panneau. Est-ce permis ?", s: "E1", o: ["Oui, l'arrêt est permis", "Non"], a: 0, fix: true, e: "Le E1 interdit le stationnement mais pas l'arrêt : déposer un passager, c'est un arrêt.", ref: "E1" },
  { id: "st10", t: "stationnement", q: "Vous stationnez la nuit, hors agglomération, sur une chaussée non éclairée. Que faites-vous ?", o: ["J'allume les feux de position ou de stationnement", "J'allume les feux de détresse pour toute la nuit", "Rien : l'éclairage n'est obligatoire qu'en roulant"], a: 0,
    e: "La nuit (ou par visibilité réduite), un véhicule à l'arrêt ou en stationnement sur la chaussée doit être signalé par ses feux de position ou de stationnement, sauf exceptions (agglomération correctement éclairée…).", ref: "Art. 32" },
  { id: "st11", t: "stationnement", q: "Peut-on stationner devant l'entrée carrossable d'une propriété (entrée de garage) ?", o: ["Non", "Oui, si on reste moins de 2 h", "Oui, en dehors des heures de bureau"], a: 0, e: "Stationnement interdit devant les entrées carrossables (sauf, selon le cas, pour le véhicule dont la plaque est affichée par le propriétaire).", ref: "Art. 25" },

  /* =================== AUTOROUTE =================== */
  { id: "a1", t: "autoroute", g: true, q: "Sur autoroute, vous avez dépassé la sortie que vous vouliez prendre. Vous :", s: "F5", o: ["Faites marche arrière sur la bande d'arrêt d'urgence", "Continuez jusqu'à la sortie suivante", "Faites demi-tour par la berme centrale"], a: 1,
    e: "Sur autoroute, demi-tour et marche arrière sont strictement interdits (y compris sur la bande d'arrêt d'urgence). On continue jusqu'à la sortie suivante.", ref: "Art. 21" },
  { id: "a2", t: "autoroute", g: true, q: "Vous vous insérez sur l'autoroute par la bande d'accélération. Qui a la priorité ?", o: ["Moi, car j'arrive par la droite des véhicules", "Les véhicules qui circulent déjà sur l'autoroute", "Celui qui roule le plus vite des deux"], a: 1,
    e: "Celui qui s'insère cède le passage aux véhicules circulant sur l'autoroute. On utilise la bande d'accélération pour prendre une vitesse proche de celle du trafic et s'insérer dans un créneau.", p: "Pas de tirette ici : la bande d'accélération n'est pas une réduction de bandes.", ref: "Art. 12.4" },
  { id: "a3", t: "autoroute", q: "Quel est le rôle de la bande d'arrêt d'urgence ?", o: ["Dépasser par la droite quand il y a des bouchons sur l'autoroute", "S'arrêter en cas de nécessité absolue (ou rouler si un signal le permet)", "Rouler lentement quand on cherche sa sortie ou son chemin"], a: 1, e: "La bande d'arrêt d'urgence est réservée aux arrêts de nécessité absolue. Y circuler est interdit, sauf si un signal l'autorise (bande ouverte au trafic).", ref: "Art. 21" },
  { id: "a4", t: "autoroute", g: true, q: "Au-dessus de votre bande, un panneau lumineux affiche une croix rouge. Vous :", o: ["Quittez cette bande dès que possible en sécurité", "Continuez prudemment sur cette bande", "Vous arrêtez sur place"], a: 0, e: "Croix rouge = bande fermée (accident, travaux…). Vous devez la quitter. Flèche oblique = se rabattre dans la direction indiquée.", ref: "Signaux à message variable" },
  { id: "a5", t: "autoroute", q: "Sur une autoroute à trois bandes, quelle bande devez-vous normalement utiliser ?", o: ["La plus à droite possible", "Celle du milieu", "Celle de gauche si je roule à 120"], a: 0, e: "On circule sur la bande la plus à droite possible. Les bandes de gauche servent à dépasser. Rester à gauche sans raison gêne et est sanctionnable.", ref: "Art. 9.3" },
  { id: "a6", t: "autoroute", q: "Votre voiture tombe en panne sur l'autoroute et ne peut plus rouler. Qui peut la dépanner ou la remorquer sur place ?", o: ["Un dépanneur agréé, appelé via votre assistance ou la police", "Un ami avec une corde de remorquage, jusqu'à la sortie", "Vous-même, en la poussant sur la bande d'arrêt d'urgence"], a: 0, e: "Sur autoroute, les interventions de dépannage sont réservées aux dépanneurs agréés par la Région. Si la voiture roule encore, rejoignez la prochaine sortie, un parking ou une zone refuge ; sinon : gilet, passagers derrière la glissière, feux de détresse, et appel à l'assistance ou au 112.", p: "Pousser ou remorquer soi-même une voiture sur autoroute est extrêmement dangereux.", ref: "Police fédérale / Touring" },
  { id: "a7", t: "autoroute", q: "Un cyclomoteur peut-il circuler sur l'autoroute ?", o: ["Non", "Oui, sur la bande d'arrêt d'urgence", "Oui s'il roule à 45 km/h"], a: 0, e: "L'autoroute est interdite aux piétons, cyclistes, cyclomoteurs, trottinettes, et aux véhicules incapables d'atteindre 70 km/h en palier (code actuel).", ref: "Art. 21.1" },
  { id: "a8", t: "autoroute", g: true, q: "Vous remarquez qu'un véhicule roule à contresens sur l'autoroute (alerte radio). Que faites-vous ?", o: ["Je roule à droite, je ralentis, j'évite de dépasser et je reste attentif", "Je roule sur la bande de gauche pour le voir arriver de loin", "Je m'arrête sur la bande d'arrêt d'urgence et je l'attends"], a: 0, e: "Un conducteur à contresens arrive généralement sur ce qu'il croit être SA bande de droite… donc votre bande de gauche. Restez à droite, ralentissez, ne dépassez pas, augmentez les distances.", ref: "Conduite défensive" },
  { id: "a9", t: "autoroute", q: "Vous arrivez sur un embouteillage soudain sur l'autoroute. Que pouvez-vous faire pour prévenir ceux qui vous suivent ?", o: ["Allumer brièvement les feux de détresse", "Freiner par à-coups violents", "Allumer les feux de route"], a: 0, e: "Les feux de détresse peuvent être utilisés pour avertir les usagers qui suivent d'un ralentissement brusque ou d'un obstacle (embouteillage).", ref: "Art. 31" },
  { id: "a10", t: "autoroute", q: "Sur autoroute, les camions de plus de 3,5 t doivent garder entre eux une distance minimale de :", o: ["20 m", "50 m", "100 m"], a: 1, fix: true, e: "Les véhicules de plus de 3,5 t (et ceux > 7 m) doivent maintenir entre eux au moins 50 m sur les autoroutes et routes où la vitesse est supérieure à 50 km/h. Pour vous : la règle des 2 secondes.", ref: "Art. 18.2" },

  /* =================== VULNÉRABLES & ZONES =================== */
  { id: "u1", t: "vulnerables", g: true, q: "Un piéton s'apprête à traverser sur un passage pour piétons (circulation non réglée). Vous :", s: "A21", o: ["Passez si vous êtes plus rapide", "Le laissez traverser", "Klaxonnez pour qu'il attende"], a: 1,
    e: "Vous devez laisser passer les piétons engagés ou qui vont s'engager sur un passage pour piétons. Vous ne pouvez vous en approcher qu'à vitesse modérée.", ref: "Art. 40.2" },
  { id: "u2", t: "vulnerables", q: "Des cyclistes peuvent-ils rouler en sens inverse dans une rue à sens unique ?", o: ["Oui, si un panneau additionnel (vélo, sens unique limité) le permet", "Non, jamais : un sens unique vaut pour tous les véhicules", "Oui, toujours, dans toutes les rues à sens unique"], a: 0,
    e: "Avec le panneau additionnel M (vélo sous le C1 / F19), la rue est en « sens unique limité » (SUL) : les cyclistes peuvent la remonter à contresens. Restez attentif, surtout aux carrefours.", ref: "M2-M5" },
  { id: "u3", t: "vulnerables", g: true, q: "Dans une rue cyclable (F111), pouvez-vous dépasser un cycliste en voiture ?", s: "F111", o: ["Oui, en laissant 1 m", "Non", "Oui, s'il roule à moins de 15 km/h"], a: 1,
    e: "Dans une rue cyclable, les véhicules à moteur ne peuvent pas dépasser les cyclistes, qui peuvent occuper toute la largeur de leur côté. Vitesse max : 30 km/h.", ref: "Rue cyclable (F111)" },
  { id: "u4", t: "vulnerables", q: "Jusqu'à quel âge un enfant à vélo peut-il rouler sur le trottoir ?", o: ["Moins de 10 ans", "Moins de 12 ans", "Moins de 14 ans"], a: 0, fix: true, e: "Les cyclistes de moins de 10 ans peuvent circuler sur le trottoir (et les accotements), à condition de ne pas gêner ni mettre en danger les piétons.", ref: "Code de la route (cyclistes)" },
  { id: "u5", t: "vulnerables", q: "Une trottinette électrique (engin de déplacement motorisé) peut circuler au maximum à :", o: ["18 km/h", "25 km/h", "45 km/h"], a: 1, fix: true,
    e: "Les engins de déplacement motorisés (trottinettes électriques…) sont limités à 25 km/h. Depuis juillet 2022 : âge minimum 16 ans (sauf exceptions), interdits sur le trottoir (sauf autorisation), pas de passager.", ref: "Engins de déplacement motorisés" },
  { id: "u6", t: "vulnerables", q: "En principe, où doit circuler une trottinette électrique ?", o: ["Sur le trottoir, à vitesse réduite", "Sur la piste cyclable si elle existe, sinon sur la chaussée", "Uniquement sur la chaussée, jamais sur la piste cyclable"], a: 1, e: "Les utilisateurs d'engins de déplacement motorisés suivent les règles des cyclistes : piste cyclable si elle existe, sinon chaussée. Le trottoir leur est interdit (sauf signalisation).", ref: "Engins de déplacement motorisés" },
  { id: "u7", t: "vulnerables", q: "Une rue scolaire (fermée par barrière ou panneau C3 avec la mention « rue scolaire ») : un véhicule autorisé (riverain) peut y circuler :", o: ["Au pas, en cédant le passage aux piétons et cyclistes", "À 30 km/h, comme dans une zone 30", "À 20 km/h, comme dans une zone résidentielle"], a: 0,
    e: "Aux heures d'entrée et de sortie, la rue scolaire est réservée aux piétons et cyclistes. Les véhicules autorisés (riverains, secours…) y roulent au pas en leur cédant le passage.", ref: "Rue scolaire" },
  { id: "u8", t: "vulnerables", g: true, q: "Dans une zone résidentielle (F12a), un enfant joue au milieu de la rue. Qui doit faire attention ?", s: "F12a", o: ["Lui : les piétons doivent toujours rester sur le trottoir", "Vous : les piétons peuvent utiliser toute la largeur et jouer", "Personne en particulier, chacun fait attention"], a: 1,
    e: "En zone résidentielle, les piétons peuvent utiliser toute la largeur de la voie publique et les jeux y sont autorisés. Vous roulez à 20 km/h max, et si nécessaire vous vous arrêtez. (Les piétons ne doivent pas entraver inutilement la circulation.)", ref: "Zone résidentielle / de rencontre (F12a)" },
  { id: "u9", t: "vulnerables", q: "Hors agglomération, des cyclistes roulent à deux de front. Est-ce permis ?", o: ["Oui, sauf si le croisement devient impossible : ils se mettent en file", "Non, jamais : les cyclistes doivent toujours rouler en file", "Oui, et ils peuvent même rouler à quatre de front"], a: 0, e: "Les cyclistes peuvent rouler à deux de front. Hors agglomération, ils doivent se mettre en file lorsqu'un véhicule arrive en sens inverse et que le croisement serait impossible sinon.", ref: "Art. 43" },
  { id: "u10", t: "vulnerables", g: true, q: "En agglomération, un bus quitte son arrêt en mettant son clignotant. Vous :", o: ["Accélérez pour passer avant qu'il ne démarre", "Ralentissez et au besoin arrêtez-vous pour le laisser partir", "Continuez : le bus doit attendre que la voie soit libre"], a: 1, e: "En agglomération, vous devez ralentir et au besoin vous arrêter pour permettre au bus de quitter son arrêt quand il l'a signalé avec ses clignotants.", ref: "Art. 39bis" },
  { id: "u11", t: "vulnerables", q: "Un car scolaire est arrêté, feux orange clignotants allumés, avec des enfants qui en descendent. Vous :", o: ["Le dépassez à vitesse normale, il est à l'arrêt", "Ralentissez fortement et êtes prêt à vous arrêter", "Klaxonnez pour prévenir les enfants de votre passage"], a: 1, e: "Un véhicule de transport scolaire à l'arrêt avec ses feux orange clignotants : ralentissez et, si nécessaire, arrêtez-vous. Un enfant peut surgir devant ou derrière le car.", ref: "Art. 39" },
  { id: "u12", t: "vulnerables", q: "Un cavalier ou un troupeau arrive en face sur une route de campagne. Vous :", o: ["Ralentissez, laissez une large distance, évitez klaxon et accélérations", "Klaxonnez de loin pour qu'ils se rangent sur le côté", "Passez rapidement pour rester le moins longtemps près des animaux"], a: 0, e: "Les animaux réagissent de façon imprévisible au bruit et à la vitesse. Ralentir, s'écarter, au besoin s'arrêter.", ref: "Art. 41" },
  { id: "u13", t: "vulnerables", q: "Une personne aveugle (canne blanche) ou accompagnée d'un chien-guide traverse. Vous :", o: ["Prenez toutes les précautions et la laissez passer", "Klaxonnez doucement pour l'aider à se repérer", "La contournez sans ralentir, elle vous entend"], a: 0, e: "Les conducteurs doivent prendre toutes les précautions envers les personnes aveugles (canne blanche) ou malvoyantes, et les laisser traverser.", ref: "Art. 40.5" },
  { id: "u14", t: "vulnerables", q: "Avant d'ouvrir votre portière côté rue, la meilleure technique est :", o: ["Ouvrir avec la main opposée pour tourner la tête et voir derrière", "Ouvrir rapidement pour gêner le moins longtemps possible", "Regarder seulement dans le rétroviseur intérieur avant d'ouvrir"], a: 0,
    e: "Il est interdit d'ouvrir une portière sans s'assurer que cela ne crée pas de danger. Ouvrir avec la main opposée oblige à pivoter et à vérifier l'angle mort : un cycliste « emportiéré » peut être gravement blessé.", ref: "Art. 51" },
  { id: "u15", t: "vulnerables", q: "Un « speed pedelec » (vélo électrique jusqu'à 45 km/h) est considéré comme :", o: ["Un vélo ordinaire : aucun casque ni plaque n'est exigé", "Un cyclomoteur (classe P) : casque, plaque, permis AM, assurance", "Une moto : permis A obligatoire"], a: 1, e: "Le speed pedelec est un cyclomoteur de classe P : casque obligatoire, plaque, assurance, permis AM (ou B). Il peut emprunter la piste cyclable dans certaines conditions.", ref: "Cyclomoteurs classe P" },

  /* =================== ALCOOL, DROGUES, GSM, FATIGUE =================== */
  { id: "al1", t: "alcool", g: true, q: "Pour un conducteur de voiture (permis B, non professionnel), le taux d'alcool maximal autorisé dans le sang est de :", o: ["0,2 g/l", "0,5 g/l", "0,8 g/l"], a: 1, fix: true,
    e: "0,5 g/l de sang (0,22 mg/l d'air alvéolaire expiré). Pour les conducteurs professionnels (camion, bus, taxi…), c'est 0,2 g/l.", p: "Ce n'est pas « 2 verres et c'est bon » : selon le poids, le sexe, la fatigue, le repas, un seul verre peut suffire à vous rendre dangereux.", ref: "Loi du 16 mars 1968, art. 34" },
  { id: "al2", t: "alcool", g: true, q: "Depuis le 1er juillet 2026, si un contrôle montre que vous dépassez le taux légal d'alcool, quelle est la durée minimale de l'interdiction de conduire immédiate (retrait du permis) ?", o: ["3 heures", "6 heures", "12 heures"], a: 2, fix: true,
    e: "Depuis le 1er juillet 2026, l'interdiction de conduire est fixée à 12 heures dans tous les cas de dépassement du taux légal (avant : 3, 6 ou 12 h selon le taux). S'y ajoute une amende (197 € au premier palier) ou une convocation au tribunal, selon le taux.", ref: "Réforme du 1er juillet 2026 (SPF Police)" },
  { id: "al3", t: "alcool", g: true, q: "Quel est le moyen efficace pour faire baisser son taux d'alcool avant de conduire ?", o: ["Boire un café serré avant de partir", "Prendre une douche froide et manger", "Attendre : seul le temps élimine l'alcool"], a: 2,
    e: "Le foie élimine environ 0,1 à 0,15 g/l par heure. Café, douche, air frais, chewing-gum : aucun effet sur le taux. Seul le temps compte… parfois jusqu'au lendemain matin.", ref: "Sécurité routière" },
  { id: "al4", t: "alcool", g: true, q: "Pour les drogues (cannabis, cocaïne, amphétamines, ecstasy, opiacés), quelle tolérance au volant en Belgique ?", o: ["Tolérance zéro : la simple présence détectée est punissable", "Une faible dose est tolérée, comme pour l'alcool", "Seules la cocaïne et l'héroïne sont interdites"], a: 0,
    e: "Tolérance zéro : un test salivaire positif suffit (interdiction de conduire immédiate, retrait du permis de 15 jours possible et poursuites devant le tribunal). Une loi de 2026 ajoute la kétamine à la liste, dès que les tests seront disponibles.", ref: "Loi du 16 mars 1968, art. 37bis" },
  { id: "al5", t: "alcool", g: true, q: "Vous êtes arrêté à un feu rouge. Pouvez-vous lire un message sur votre GSM tenu en main ?", o: ["Oui, la voiture est immobile, ce n'est plus « conduire »", "Non, c'est interdit, même au feu ou dans un bouchon", "Oui, si le moteur est coupé par le start-stop"], a: 1,
    e: "Il est interdit d'utiliser un appareil électronique portable tenu en main en conduisant, y compris quand vous êtes immobilisé pour les besoins de la circulation (feu, bouchon). Seuls le kit mains libres ou un support fixe sont tolérés. Amende : 191 € (infraction du 3e degré depuis juillet 2026).", ref: "Art. 8.4" },
  { id: "al6", t: "alcool", q: "Un médicament porte ce pictogramme : triangle rouge avec une voiture. Que signifie-t-il ?", o: ["Il peut altérer la conduite : lire la notice, demander conseil", "Il est sans danger au volant : c'est un label de qualité", "Il interdit de conduire pendant toute la durée du traitement"], a: 0, e: "Certains médicaments (somnifères, anxiolytiques, antihistaminiques, antidouleurs forts…) altèrent la vigilance. Combinés à l'alcool, l'effet est multiplié.", ref: "Sécurité routière" },
  { id: "al7", t: "alcool", q: "Lors d'un long trajet, on conseille une pause :", o: ["Toutes les 2 heures environ", "Toutes les 5 heures", "Seulement en cas de fatigue intense"], a: 0, fix: true,
    e: "Une pause d'au moins 15 minutes toutes les 2 heures. Signes de fatigue : bâillements, yeux qui piquent, écarts de trajectoire, ne plus se souvenir des derniers kilomètres. Seul remède efficace : dormir (une sieste de 15-20 min).", ref: "Sécurité routière" },
  { id: "al8", t: "alcool", q: "Le refus de souffler (test d'haleine) est sanctionné :", o: ["Comme une conduite à plus de 1,8 g/l (le plus sévère)", "Par un simple avertissement, comme pour un premier excès", "Il n'est pas sanctionné tant que le taux réel est inconnu"], a: 0, e: "Refuser le test ou l'analyse d'haleine sans motif légitime est puni des mêmes peines que la conduite sous l'emprise de l'alcool au taux le plus élevé, avec retrait immédiat du permis.", ref: "Loi du 16 mars 1968, art. 33" },
  { id: "al9", t: "alcool", q: "Vous avez conduit avec 0,9 g/l d'alcool. Que risquez-vous en plus de l'interdiction de conduire immédiate ?", o: ["Rien d'autre : l'amende immédiate de 197 € règle l'affaire", "Un retrait de 15 jours possible et un passage au tribunal", "Un simple avertissement, s'il s'agit d'un premier contrôle"], a: 1, e: "Au-delà de 0,8 g/l (0,35 mg/l d'air expiré), il n'y a plus de perception immédiate : le parquet peut ordonner un retrait de permis de 15 jours et vous passez devant le tribunal (amende élevée, déchéance, éthylotest antidémarrage « alcolock » possible).", ref: "Loi du 16 mars 1968, art. 34 & 55" },
  { id: "al10", t: "alcool", q: "Le kit mains libres (Bluetooth) est-il permis en conduisant ?", o: ["Oui, mais il réduit l'attention : à éviter dans les situations complexes", "Non, toute communication téléphonique est interdite au volant", "Oui, sans restriction, il n'a aucun effet sur la conduite"], a: 0, e: "Téléphoner en mains libres est permis, mais la conversation détourne une partie de l'attention (« cécité d'inattention »). Vous restez responsable de garder le contrôle du véhicule.", ref: "Art. 8.4" },

  /* =================== CEINTURE & ENFANTS =================== */
  { id: "c1", t: "securite", g: true, q: "Le port de la ceinture de sécurité est obligatoire :", o: ["Uniquement à l'avant", "À l'avant et à l'arrière, pour tous", "Uniquement hors agglomération"], a: 1, e: "Ceinture obligatoire pour le conducteur et tous les passagers, à l'avant comme à l'arrière, dès qu'elle est installée. À 50 km/h, un choc sans ceinture équivaut à une chute de 3 étages.", ref: "Art. 35.1" },
  { id: "c2", t: "securite", g: true, q: "Un enfant de moins de 1,35 m doit être transporté :", o: ["Avec un dispositif de retenue adapté (siège, rehausseur)", "Avec la ceinture adulte, si l'enfant est assis à l'arrière", "Sur les genoux d'un adulte attaché, à l'arrière"], a: 0, e: "Les enfants de moins de 1,35 m doivent utiliser un dispositif de retenue pour enfants homologué adapté à leur taille/poids. Sur les genoux : jamais.", ref: "Art. 35.1.1" },
  { id: "c3", t: "securite", g: true, q: "Vous installez un siège enfant dos à la route sur le siège passager avant. Que devez-vous faire ?", o: ["Désactiver l'airbag frontal passager", "Rien de particulier", "Avancer le siège au maximum"], a: 0, e: "Un siège dos à la route devant un airbag frontal actif est interdit et extrêmement dangereux : l'airbag projetterait le siège vers l'arrière.", ref: "Art. 35.1.1" },
  { id: "c4", t: "securite", g: true, q: "Qui est responsable du port de la ceinture par un passager de moins de 18 ans ?", o: ["Le conducteur", "Le passager lui-même", "Ses parents uniquement"], a: 0, e: "Le conducteur doit veiller à ce que les passagers de moins de 18 ans portent la ceinture ou soient attachés dans un dispositif adapté.", ref: "Art. 35.1" },
  { id: "c5", t: "securite", q: "Comment régler correctement l'appui-tête ?", o: ["Le haut au niveau du haut de la tête, près de la tête", "Au niveau de la nuque, pour bien soutenir le cou", "Le plus bas possible, pour ne pas gêner la vue arrière"], a: 0, e: "Un appui-tête bien réglé (haut à hauteur du sommet du crâne, proche de la tête) réduit fortement le « coup du lapin » en cas de choc arrière.", ref: "Sécurité passive" },
  { id: "c6", t: "securite", q: "La ceinture de sécurité doit passer :", o: ["Sur l'épaule et le bassin, bien à plat et tendue", "Sous le bras, pour ne pas frotter le cou", "Sur le ventre, juste au-dessus du nombril"], a: 0, e: "Sangle diagonale sur l'épaule (pas le cou, pas sous le bras), sangle ventrale basse sur le bassin. Une femme enceinte place la sangle ventrale sous le ventre.", ref: "Sécurité passive" },
  { id: "c7", t: "securite", q: "Faute de place, un enfant de 4 ans (1,05 m) peut-il voyager sans siège à l'arrière, attaché avec la ceinture ?", o: ["Oui, si un 3e siège ne peut pas être installé et qu'il a au moins 3 ans", "Non, jamais : un enfant de moins de 1,35 m doit toujours avoir un siège", "Oui, toujours, dès qu'il voyage à l'arrière d'une voiture"], a: 0,
    e: "Exception : quand il est impossible d'installer un 3e siège enfant à l'arrière, un enfant de 3 ans ou plus peut être attaché avec la ceinture adulte. Un enfant de moins de 3 ans ne peut jamais être transporté sans dispositif adapté.", ref: "Art. 35.1.1" },

  /* =================== VÉHICULE & ÉCLAIRAGE =================== */
  { id: "e1", t: "vehicule", q: "La profondeur minimale des rainures des pneus d'une voiture est de :", o: ["1 mm", "1,6 mm", "3 mm"], a: 1, fix: true, e: "Minimum légal : 1,6 mm sur toute la bande de roulement (témoins d'usure). En pratique, sous 3 mm, l'adhérence sur route mouillée baisse fortement.", ref: "AR 15/03/1968, art. 32" },
  { id: "e2", t: "vehicule", q: "Les pneus hiver sont-ils obligatoires en Belgique ?", o: ["Oui, du 1er novembre au 31 mars", "Non, mais fortement conseillés en hiver", "Oui, s'il neige"], a: 1, e: "Pas d'obligation générale en Belgique (contrairement à l'Allemagne en conditions hivernales, au Luxembourg…). Ils restent très conseillés sous 7 °C.", ref: "Règlement technique" },
  { id: "e3", t: "vehicule", q: "Quels équipements doivent se trouver dans une voiture immatriculée en Belgique ?", o: ["Triangle, gilet fluorescent, extincteur et trousse de secours", "Gilet fluorescent seulement, le reste est conseillé", "Triangle, roue de secours et câbles de démarrage"], a: 0,
    e: "En Belgique : triangle de danger, gilet de sécurité fluorescent (à portée de main), extincteur homologué et trousse de premiers secours. Attention : le futur Code de la voie publique (2027) prévoit d'assouplir l'obligation de placer le triangle sur autoroute.", ref: "AR 15/03/1968" },
  { id: "e4", t: "vehicule", q: "La nuit, en agglomération sur une route bien éclairée, vous utilisez :", o: ["Les feux de croisement", "Les feux de route", "Les feux de position seuls"], a: 0, e: "Feux de croisement la nuit et dès que la visibilité est inférieure à 200 m. Les feux de position seuls ne suffisent jamais pour rouler.", ref: "Art. 30" },
  { id: "e5", t: "vehicule", g: true, q: "Vous roulez la nuit en feux de route. Une voiture arrive en face. Vous :", o: ["Passez en feux de croisement", "Gardez les feux de route pour mieux voir", "Faites des appels de phares"], a: 0, e: "On passe en feux de croisement à l'approche d'un véhicule en sens inverse (et quand on suit un véhicule de près), pour ne pas éblouir.", p: "Si vous êtes ébloui : regardez le bord droit de la route et ralentissez.", ref: "Art. 30.2" },
  { id: "e6", t: "vehicule", q: "Quand pouvez-vous allumer le feu antibrouillard ARRIÈRE ?", o: ["Visibilité de moins de 100 m (brouillard, neige, forte pluie)", "Dès qu'il pleut, pour être mieux vu par ceux qui suivent", "La nuit sur autoroute, quand la route n'est pas éclairée"], a: 0, e: "Feu de brouillard arrière : uniquement par visibilité < 100 m due au brouillard, à la neige ou à une pluie intense. Sinon, il éblouit ceux qui vous suivent.", ref: "Art. 30.3" },
  { id: "e7", t: "vehicule", q: "Vous devez faire contrôler votre voiture au contrôle technique :", o: ["À la revente d'une occasion, et périodiquement selon l'âge du véhicule", "Jamais pour une voiture privée, seulement pour les taxis", "Uniquement après un accident ou une réparation importante"], a: 0, e: "Contrôle technique périodique (premier contrôle après 4 ans pour une voiture neuve, puis selon le régime régional), et obligatoire lors de la vente d'un véhicule d'occasion.", ref: "AR 15/03/1968, art. 23" },
  { id: "e8", t: "vehicule", q: "Un témoin rouge s'allume au tableau de bord (pression d'huile, température, freins). Que faites-vous ?", o: ["Je m'arrête dès que possible en sécurité et je coupe le moteur", "Je continue jusqu'à destination puis je vais au garage", "Je roule plus doucement jusqu'au garage le plus proche"], a: 0, e: "Rouge = danger immédiat : arrêt en sécurité dès que possible. Orange = anomalie à faire vérifier rapidement.", ref: "Connaissance du véhicule" },
  { id: "e9", t: "vehicule", q: "Quand l'usage de l'avertisseur sonore (klaxon) est-il permis ?", o: ["Pour éviter un accident ; hors agglo, pour annoncer un dépassement", "Pour saluer quelqu'un ou remercier un autre conducteur", "Pour signaler à un autre conducteur qu'il a commis une faute"], a: 0, e: "Le klaxon sert à éviter un accident (et, hors agglomération, à avertir d'un dépassement). La nuit, on préfère l'appel de phares bref.", ref: "Art. 33" },
  { id: "e10", t: "vehicule", q: "Les feux de détresse peuvent être utilisés :", o: ["Véhicule dangereux (panne, accident), ralentissement brusque, remorquage", "Pour s'arrêter un instant en double file ou devant un garage", "Par forte pluie, pour être mieux vu par les autres"], a: 0, e: "Les feux de détresse ne permettent JAMAIS de stationner où c'est interdit (« je mets les warnings, j'en ai pour 2 minutes » = infraction).", ref: "Art. 31" },

  /* =================== PANNE, ACCIDENT & SECOURS =================== */
  { id: "ac1", t: "accident", g: true, q: "Vous êtes témoin d'un accident avec blessés. Dans quel ordre agissez-vous ?", o: ["Sécuriser les lieux, alerter (112), secourir", "Secourir, sécuriser, alerter", "Alerter, puis repartir"], a: 0, fix: true,
    e: "S-A-S : Sécuriser (feux de détresse, gilet, triangle, se garer en sécurité), Alerter le 112, Secourir. Ne déplacez pas un blessé sauf danger immédiat (incendie, risque de suraccident).", ref: "Premiers secours" },
  { id: "ac2", t: "accident", q: "Quel numéro appeler en cas d'urgence partout en Europe ?", o: ["112", "100", "911"], a: 0, fix: true, e: "112 : numéro d'urgence européen gratuit (pompiers, ambulance). En Belgique, 101 = police. L'application 112 BE permet aussi d'alerter.", ref: "Secours" },
  { id: "ac3", t: "accident", q: "À quelle distance minimale placez-vous le triangle de danger sur une route ordinaire ?", o: ["10 m", "30 m", "100 m"], a: 1, fix: true, e: "Au moins 30 m du véhicule sur une route ordinaire (100 m sur autoroute), visible à 50 m au moins par les usagers qui approchent.", ref: "Art. 51" },
  { id: "ac4", t: "accident", q: "Sur autoroute, le triangle se place à au moins :", o: ["30 m", "50 m", "100 m"], a: 2, fix: true, e: "100 m sur autoroute (et routes pour automobiles). Placez-vous derrière la glissière pour attendre les secours : la bande d'arrêt d'urgence est très dangereuse.", ref: "Art. 51" },
  { id: "ac5", t: "accident", q: "Vous tombez en panne sur l'autoroute. Que faites-vous en sortant du véhicule ?", o: ["Gilet enfilé avant de sortir, sortie côté glissière, attente derrière elle", "Je reste dans la voiture, ceinture détachée, feux de détresse allumés", "J'attends sur la bande d'arrêt d'urgence, devant la voiture"], a: 0, e: "Gilet enfilé avant de sortir, tout le monde derrière la glissière de sécurité, feux de détresse, triangle si c'est possible sans danger, puis appel à l'assistance.", ref: "Art. 51 / Gilet" },
  { id: "ac6", t: "accident", q: "Accident avec dégâts matériels seulement, sans désaccord. Que remplissez-vous ?", o: ["Le constat européen d'accident (constat amiable)", "Rien, chacun s'arrange avec son garagiste", "Un procès-verbal de police, obligatoire dans tous les cas"], a: 0, e: "Le constat européen d'accident (papier ou application e-constat) est rempli et signé par les deux parties, puis envoyé aux assureurs (en général dans les 8 jours).", ref: "Assurance RC" },
  { id: "ac7", t: "accident", g: true, q: "Vous êtes impliqué dans un accident. Pouvez-vous quitter les lieux sans laisser vos coordonnées ?", o: ["Non : c'est un délit de fuite", "Oui, si les dégâts sont faibles", "Oui, si personne ne vous a vu"], a: 0, e: "Le délit de fuite est sévèrement puni (amende, déchéance du droit de conduire, examens de réintégration). Vous devez rester sur place ou au minimum laisser votre identité.", ref: "Loi du 16 mars 1968, art. 33" },
  { id: "ac8", t: "accident", q: "Un motard blessé est inconscient et respire. Retirez-vous son casque ?", o: ["Non, sauf s'il ne respire plus et qu'il faut le réanimer", "Oui, toujours, pour vérifier qu'il n'est pas blessé à la tête", "Oui, pour qu'il respire mieux en attendant les secours"], a: 0, e: "On ne retire pas le casque d'un motard qui respire (risque de lésion de la colonne). Seulement en cas d'arrêt respiratoire, et avec précaution.", ref: "Premiers secours" },
  { id: "ac9", t: "accident", q: "Pour une victime inconsciente qui respire normalement, la bonne position est :", o: ["La position latérale de sécurité (PLS)", "Assise, adossée à la voiture", "Sur le dos, jambes surélevées"], a: 0, e: "PLS pour une personne inconsciente qui respire : elle évite qu'elle s'étouffe avec sa langue ou des vomissements. Si elle ne respire pas : 112 + réanimation (massage cardiaque, DEA).", ref: "Premiers secours" },

  /* =================== CONDUITE & ANTICIPATION (perception des risques) =================== */
  { id: "k1", t: "conduite", q: "Quelle distance de sécurité minimale conseille-t-on avec le véhicule qui vous précède, par temps sec ?", o: ["1 seconde", "2 secondes", "5 mètres"], a: 1, fix: true,
    e: "Règle des 2 secondes : quand le véhicule devant passe un repère, comptez « 1001, 1002 ». Doublez par temps de pluie, triplez sur neige/verglas. Le futur code (2027) rend les 2 secondes obligatoires au-delà de 50 km/h.", ref: "Art. 18" },
  { id: "k2", t: "conduite", q: "Un ballon roule sur la chaussée entre deux voitures garées. Quel est le principal danger ?", o: ["Un enfant qui va courir derrière le ballon", "Le ballon qui abîme la carrosserie", "Aucun"], a: 0, e: "Anticipation : un ballon annonce presque toujours un enfant. Freinez et préparez-vous à vous arrêter.", ref: "Perception des risques" },
  { id: "k3", t: "conduite", q: "Vous suivez un camion de près sur une route étroite. Quel est le risque principal ?", o: ["Il cache la route devant lui, et il ne vous voit pas", "Aucun, il vous protège du vent et des projections", "Seulement une consommation de carburant plus élevée"], a: 0, e: "Restez assez loin pour voir le rétroviseur du camion (s'il ne vous voit pas, vous êtes dans son angle mort) et pour voir la route devant lui.", ref: "Perception des risques" },
  { id: "k4", t: "conduite", q: "Un camion tourne à droite à un carrefour. Un cycliste se trouve à sa droite. Quel est le danger ?", o: ["L'angle mort : le chauffeur ne voit peut-être pas le cycliste", "Aucun, le cycliste est prioritaire et le chauffeur le sait", "Le camion va reculer pour prendre son virage"], a: 0, e: "L'angle mort des poids lourds est une cause majeure d'accidents graves avec des cyclistes et piétons. En voiture aussi : vérifiez votre angle mort droit avant de tourner.", ref: "Perception des risques" },
  { id: "k5", t: "conduite", q: "Par forte pluie, votre voiture « flotte » et la direction devient légère. C'est de l'aquaplaning. Vous :", o: ["Lâchez l'accélérateur, volant droit, sans freinage brusque", "Freinez à fond pour retrouver l'adhérence au plus vite", "Donnez un coup de volant pour sortir rapidement de la flaque"], a: 0, e: "Aquaplaning : un film d'eau sépare le pneu de la route. Lâchez l'accélérateur, gardez les roues droites, débrayez si nécessaire, attendez de retrouver l'adhérence.", ref: "Conduite défensive" },
  { id: "k6", t: "conduite", q: "Un enfant se tient au bord du trottoir et regarde de l'autre côté de la rue où se trouve un marchand de glaces. Vous :", o: ["Ralentissez, prêt à freiner : il peut traverser sans regarder", "Gardez votre vitesse : il vous a vu et va attendre que vous passiez", "Klaxonnez fort pour qu'il reste sur le trottoir"], a: 0, e: "Les enfants ont un champ de vision réduit, évaluent mal les vitesses et peuvent agir sur une impulsion. Leur attention est ailleurs.", ref: "Perception des risques" },
  { id: "k7", t: "conduite", q: "Une voiture garée a ses feux de recul allumés. Vous :", o: ["Ralentissez : elle va probablement reculer", "Accélérez pour passer avant qu'elle bouge", "Klaxonnez et gardez votre vitesse"], a: 0, e: "Feux de recul allumés = manœuvre imminente. Le conducteur ne vous a peut-être pas vu.", ref: "Perception des risques" },
  { id: "k8", t: "conduite", q: "En virage, quand faut-il freiner ?", o: ["Avant le virage, en ligne droite", "Au milieu du virage, quand on voit la sortie", "À l'entrée du virage, en braquant"], a: 0, e: "On adapte sa vitesse AVANT le virage, en ligne droite. Freiner fort en courbe peut déséquilibrer le véhicule. On ré-accélère progressivement en sortie.", ref: "Conduite" },
  { id: "k9", t: "conduite", q: "Pour une conduite économique et écologique, il vaut mieux :", o: ["Anticiper, rouler à allure régulière, monter tôt les rapports", "Rouler en sous-régime en accélérant fort à chaque reprise", "Laisser le moteur tourner à l'arrêt pour qu'il reste chaud"], a: 0, e: "Éco-conduite : anticipation, frein moteur, rapports élevés tôt (≈ 2 000-2 500 tr/min), pression des pneus correcte, pas de poids inutile ni de coffre de toit vide.", ref: "Éco-conduite" },
  { id: "k10", t: "conduite", q: "Avant de changer de bande, l'ordre correct est :", o: ["Rétroviseurs, angle mort, clignotant, puis manœuvre", "Clignotant puis manœuvre immédiate", "Manœuvre puis clignotant"], a: 0, fix: true, e: "Rétroviseurs → regard angle mort → clignotant (assez tôt) → nouveau contrôle → manœuvre progressive.", ref: "Art. 12.4" },
  { id: "k11", t: "conduite", q: "Sur une route de campagne, vous voyez de la boue sur la chaussée près d'un champ. Que pouvez-vous anticiper ?", o: ["Une chaussée glissante et un tracteur qui peut sortir d'un chemin", "Une zone de travaux où la vitesse est limitée à 30 km/h", "Rien de particulier, la boue n'a pas d'effet sur l'adhérence"], a: 0, e: "Boue = adhérence réduite et présence probable d'engins agricoles lents ou de véhicules sortant d'un chemin de terre.", ref: "Perception des risques" },
  { id: "k12", t: "conduite", q: "La nuit, un piéton habillé en sombre sans réfléchissant est visible en feux de croisement à environ :", o: ["25 m", "100 m", "150 m"], a: 0, fix: true, e: "En vêtements sombres, un piéton n'est visible qu'à 20-25 m en feux de croisement (contre ~150 m avec des éléments réfléchissants). À 70 km/h, c'est trop court pour s'arrêter : adaptez votre vitesse la nuit.", ref: "Perception des risques" },
  { id: "k13", t: "conduite", q: "Les aides à la conduite (freinage d'urgence automatique, aide au maintien dans la bande, ISA) obligatoires sur les voitures neuves depuis juillet 2024 :", o: ["Vous aident, mais vous restez entièrement responsable", "Remplacent le conducteur dans les situations d'urgence", "Permettent de lâcher le volant sur autoroute"], a: 0,
    e: "Depuis juillet 2024, toutes les voitures neuves vendues dans l'UE doivent avoir plusieurs aides (adaptation intelligente de la vitesse, freinage d'urgence, détection de somnolence…). Ce sont des aides : le conducteur reste responsable.", ref: "Règlement (UE) 2019/2144" },

  /* =================== PERMIS, DOCUMENTS & SANCTIONS =================== */
  { id: "pm1", t: "permis", q: "Combien de questions comporte l'examen théorique du permis B et quel est le seuil de réussite ?", o: ["40 questions, 32/40", "50 questions, 41/50", "50 questions, 35/50"], a: 1, fix: true,
    e: "50 questions, il faut au moins 41/50. Une faute « légère » retire 1 point, une faute grave en retire 5 : deux fautes graves = 40/50 = échec, même avec tout le reste juste.", ref: "Examen théorique (GOCA / AIBV / SBAT…)" },
  { id: "pm2", t: "permis", q: "Combien de temps la réussite de l'examen théorique reste-t-elle valable pour passer à la suite (permis provisoire / pratique) ?", o: ["1 an", "3 ans", "Toute la vie"], a: 1, fix: true, e: "L'attestation de réussite de l'examen théorique est valable 3 ans.", ref: "AR 23/03/1998" },
  { id: "pm3", t: "permis", r: ["W"], q: "En Wallonie, depuis le 1er janvier 2026, que faut-il avoir réussi pour se présenter à l'examen pratique wallon ?", o: ["Le théorique ET le test de perception des risques (TPR), en Wallonie", "Le théorique seulement, réussi dans n'importe quelle Région", "Le théorique et 20 heures de leçons, sans autre test"], a: 0,
    e: "Depuis le 1er janvier 2026, la formation se fait dans une seule Région : pour l'examen pratique en Wallonie, il faut avoir réussi en Wallonie le théorique et le test de perception des risques (vidéos où l'on clique sur les dangers). Le TPR suit la validité du théorique (3 ans).", ref: "Réforme wallonne / AIBV 2026" },
  { id: "pm4", t: "permis", q: "Quels documents devez-vous pouvoir présenter lors d'un contrôle ?", o: ["Permis, certificat d'immatriculation, assurance (et contrôle technique)", "Carte d'identité, carnet d'entretien et facture d'achat", "Permis et carte d'identité seulement, le reste est en ligne"], a: 0, e: "Permis (ou permis provisoire), certificat d'immatriculation, certificat d'assurance, certificat de visite (CT) si le véhicule y est soumis. Le permis provisoire doit être accompagné de la carte d'identité.", ref: "Documents de bord" },
  { id: "pm5", t: "permis", q: "Avec un permis provisoire accompagné d'un guide, quel signe doit être apposé à l'arrière du véhicule ?", o: ["Un « L » blanc sur fond bleu", "Un « A » rouge sur fond blanc", "Un « 90 » dans un cercle rouge"], a: 0, e: "Le signe distinctif « L » (lettre blanche sur fond bleu) est obligatoire quand on roule avec un guide (filière libre).", ref: "AR 23/03/1998" },
  { id: "pm6", t: "permis", q: "Le permis à points existe-t-il en Belgique (novembre 2026) ?", o: ["Oui, depuis 2024, avec 12 points", "Non : une loi existe depuis 1990, jamais appliquée", "Oui, mais seulement pour les jeunes conducteurs"], a: 1, e: "Une loi de 1990 prévoit un permis à points mais elle n'a jamais été exécutée. Le sujet revient régulièrement en discussion politique, sans application à ce jour.", ref: "Actualité 2026" },
  { id: "pm7", t: "permis", q: "L'assurance responsabilité civile (RC auto) est :", o: ["Obligatoire pour tout véhicule automoteur en circulation", "Facultative, mais fortement conseillée", "Obligatoire seulement pour les voitures neuves"], a: 0, e: "La RC auto est obligatoire : elle indemnise les dommages que vous causez aux autres. Rouler sans assurance est une infraction très grave (déchéance possible).", ref: "Loi du 21/11/1989" },
  { id: "pm8", t: "permis", q: "Depuis le 1er juillet 2026, les amendes routières par perception immédiate :", o: ["Ont augmenté d'environ 10 %", "Ont diminué", "N'ont pas changé depuis 2017"], a: 0,
    e: "Les montants ont été relevés d'environ 10 % au 1er juillet 2026 (première indexation depuis 2017). Barème : 64 € (1er degré), 128 € (2e), 191 € (3e), 520 € (4e). Vitesse : 58 € jusqu'à 10 km/h d'excès, puis par km/h supplémentaire.", ref: "AR 2026, police.be" },
  { id: "pm9", t: "permis", q: "Conduire pendant une déchéance du droit de conduire est :", o: ["Une infraction grave, jugée par le tribunal de police", "Une faute tolérée pour les trajets domicile-travail", "Une simple perception immédiate de 58 €, sans plus"], a: 0, e: "Conduire malgré une déchéance est puni sévèrement. Depuis 2026, cela vise aussi les trottinettes électriques et cyclomoteurs A, dont la conduite pendant une déchéance devient une infraction à part entière.", ref: "Loi du 16 mars 1968 / réforme 2026" },
  { id: "pm10", t: "permis", q: "Le permis de conduire belge au format carte bancaire est valable :", o: ["10 ans, puis à renouveler", "À vie", "5 ans"], a: 0, fix: true, e: "Le permis au format carte est valable 10 ans (sa validité administrative), à renouveler à la commune. Le droit de conduire, lui, ne disparaît pas.", ref: "Directive 2006/126/CE" },
];
